"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { useErpConfirmation } from "@/components/providers/erp-confirmation-provider";
import { Loader2, Trash2, ExternalLink, Globe, History, Pencil, Check, X, Link2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { formatCurrency } from "@/lib/utils";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import { toast } from "@/lib/erp-feedback";
import { addListing, updateListing, deleteListing, getListings, getListingHistory } from "@/app/(dashboard)/inventory/listing-actions";

const formSchema = z.object({
    platform: z.string().min(1, "Platform is required"),
    listingUrl: z.string().url("Invalid URL").optional().or(z.literal("")),
    listingRef: z.string().optional(),
    listedPrice: z.coerce.number().positive("Price must be positive"),
    status: z.string().default("ACTIVE"),
});

interface Listing {
    id: string;
    platform: string;
    listingUrl: string | null;
    listingRef: string | null;
    listedPrice: number;
    currency: string;
    status: string;
    createdAt: Date;
}

interface ListingManagerProps {
    inventoryId: string;
    sku: string;
    trigger?: React.ReactNode;
    open?: boolean;
    onOpenChange?: (open: boolean) => void;
}

interface PriceHistoryItem {
    price: number;
    changedAt: Date | string;
    changedBy?: string;
}

function ListingPriceHistory({ listingId, currency = "USD" }: { listingId: string; currency?: string }) {
    const [history, setHistory] = useState<PriceHistoryItem[]>([]);
    const [loading, setLoading] = useState(false);
    const [open, setOpen] = useState(false);

    const handleOpenChange = (isOpen: boolean) => {
        setOpen(isOpen);
        if (isOpen) {
            setLoading(true);
            getListingHistory(listingId).then(res => {
                if (res.success) setHistory(res.history);
                setLoading(false);
            });
        }
    };

    return (
        <Popover open={open} onOpenChange={handleOpenChange}>
            <PopoverTrigger asChild>
                <Button variant="ghost" size="icon" className="h-6 w-6 ml-1" title="View Price History">
                    <History className="h-3 w-3 text-muted-foreground" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-64 p-3">
                <h4 className="font-medium text-sm mb-2 border-b pb-1">Price History</h4>
                {loading ? (
                    <div className="flex justify-center p-2"><Loader2 className="h-4 w-4 animate-spin" /></div>
                ) : history.length === 0 ? (
                    <p className="text-xs text-muted-foreground">No history recorded.</p>
                ) : (
                    <div className="space-y-2 max-h-[200px] overflow-y-auto">
                        {history.map((h, i) => (
                            <div key={i} className="text-xs flex justify-between items-center border-b last:border-0 pb-1 last:pb-0">
                                <span className="font-medium">{formatCurrency(h.price, currency)}</span>
                                <div className="text-right">
                                    <div className="text-muted-foreground">{new Date(h.changedAt).toLocaleDateString()}</div>
                                    <div className="text-[10px] text-muted-foreground/70">{new Date(h.changedAt).toLocaleTimeString()}</div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </PopoverContent>
        </Popover>
    );
}

export function ListingManager({ inventoryId, sku, trigger, open, onOpenChange }: ListingManagerProps) {
    const confirm = useErpConfirmation();
    const [listings, setListings] = useState<Listing[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [internalOpen, setInternalOpen] = useState(false);
    const [showAddForm, setShowAddForm] = useState(false);

    const isControlled = open !== undefined;
    const isOpen = isControlled ? open : internalOpen;
    const setIsOpen = isControlled ? onOpenChange : setInternalOpen;

    const form = useForm({
        resolver: zodResolver(formSchema),
        defaultValues: {
            platform: "WHATSAPP",
            listingUrl: "",
            listingRef: "",
            listedPrice: 0,
            status: "ACTIVE",
        },
    });

    async function loadListings() {
        setIsLoading(true);
        const res = await getListings(inventoryId);
        if (res.success) {
            setListings(res.listings as Listing[]);
        }
        setIsLoading(false);
    }

    useEffect(() => {
        if (isOpen) {
            loadListings();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isOpen, inventoryId]);

    async function onSubmit(values: z.infer<typeof formSchema>) {
        setIsSubmitting(true);
        const res = await addListing({ ...values, inventoryId, currency: "INR" });
        setIsSubmitting(false);

        if (res.success) {
            setShowAddForm(false);
            form.reset();
            loadListings();
        }
    }

    async function handleDelete(id: string) {
        if (!(await confirm({ title: "Delete marketplace listing?", description: "This removes the listing record from this inventory item. This action cannot be undone.", confirmLabel: "Delete listing", destructive: true }))) return;
        await deleteListing(id);
        loadListings();
    }

    async function handleStatusChange(id: string, newStatus: string) {
        await updateListing(id, { status: newStatus });
        loadListings();
    }

    // Edit listing inline
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editValues, setEditValues] = useState<{ listingUrl: string; listingRef: string }>({ listingUrl: "", listingRef: "" });

    function startEditing(listing: Listing) {
        setEditingId(listing.id);
        setEditValues({
            listingUrl: listing.listingUrl || "",
            listingRef: listing.listingRef || "",
        });
    }

    function cancelEditing() {
        setEditingId(null);
        setEditValues({ listingUrl: "", listingRef: "" });
    }

    async function saveEditing(id: string) {
        const res = await updateListing(id, {
            listingUrl: editValues.listingUrl,
            listingRef: editValues.listingRef,
        });
        if (res.success) {
            toast.success("Listing updated successfully");
            loadListings();
        } else {
            toast.error("Failed to update listing");
        }
        setEditingId(null);
    }

    function copyToClipboard(text: string) {
        navigator.clipboard.writeText(text);
        toast.success("URL copied to clipboard");
    }

    return (
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
            {trigger ? (
                <DialogTrigger asChild>{trigger}</DialogTrigger>
            ) : (
                <DialogTrigger asChild>
                    <Button variant="outline" size="sm">
                        <Globe className="mr-2 h-4 w-4" /> Manage Listings
                    </Button>
                </DialogTrigger>
            )}
            <DialogContent className="max-w-3xl max-h-[80vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>Manage Listings - {sku}</DialogTitle>
                    <DialogDescription>
                        Track where this item is listed to prevent double sales.
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-6">
                    {/* Listings List */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h3 className="text-sm font-medium">Active Listings</h3>
                            <Button size="sm" onClick={() => setShowAddForm(!showAddForm)} variant={showAddForm ? "secondary" : "default"}>
                                {showAddForm ? "Cancel" : "Add Listing"}
                            </Button>
                        </div>

                        {showAddForm && (
                            <div className="rounded-lg border p-4 bg-muted/50">
                                <Form {...form}>
                                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            <FormField
                                                control={form.control}
                                                name="platform"
                                                render={({ field }) => (
                                                    <FormItem>
                                                        <FormLabel>Platform</FormLabel>
                                                        <Select onValueChange={field.onChange} defaultValue={field.value as string}>
                                                            <FormControl>
                                                                <SelectTrigger><SelectValue placeholder="Select Platform" /></SelectTrigger>
                                                            </FormControl>
                                                            <SelectContent>
                                                                <SelectItem value="WHATSAPP">WhatsApp</SelectItem>
                                                                <SelectItem value="WEBSITE">Website</SelectItem>
                                                                <SelectItem value="EBAY">eBay</SelectItem>
                                                                <SelectItem value="ETSY">Etsy</SelectItem>
                                                                <SelectItem value="AMAZON">Amazon</SelectItem>
                                                                <SelectItem value="OTHER">Other</SelectItem>
                                                            </SelectContent>
                                                        </Select>
                                                        <FormMessage />
                                                    </FormItem>
                                                )}
                                            />
                                            <FormField
                                                control={form.control}
                                                name="listedPrice"
                                                render={({ field }) => (
                                                    <FormItem>
                                                        <FormLabel>Listed Price</FormLabel>
                                                        <FormControl>
                                                            <Input type="number" {...field} value={field.value as number} />
                                                        </FormControl>
                                                        <FormMessage />
                                                    </FormItem>
                                                )}
                                            />
                                             <FormField
                                                control={form.control}
                                                name="listingUrl"
                                                render={({ field }) => (
                                                    <FormItem>
                                                        <FormLabel>URL</FormLabel>
                                                        <FormControl>
                                                            <Input placeholder="https://..." {...field} value={field.value as string} />
                                                        </FormControl>
                                                        <FormMessage />
                                                    </FormItem>
                                                )}
                                            />
                                             <FormField
                                                control={form.control}
                                                name="listingRef"
                                                render={({ field }) => (
                                                    <FormItem>
                                                        <FormLabel>Reference / ID</FormLabel>
                                                        <FormControl>
                                                            <Input placeholder="e.g. #12345" {...field} value={field.value as string} />
                                                        </FormControl>
                                                        <FormMessage />
                                                    </FormItem>
                                                )}
                                            />
                                        </div>
                                        <Button type="submit" disabled={isSubmitting}>
                                            {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                            Save Listing
                                        </Button>
                                    </form>
                                </Form>
                            </div>
                        )}

                        {isLoading ? (
                            <div className="flex justify-center p-4"><Loader2 className="h-6 w-6 animate-spin text-muted-foreground" /></div>
                        ) : listings.length === 0 ? (
                            <div className="text-center p-8 border border-dashed rounded-lg text-muted-foreground text-sm">
                                No listings found. Add one to track where this item is being sold.
                            </div>
                        ) : (
                            <div className="grid gap-4">
                                {listings.map((listing) => (
                                    <div key={listing.id} className="flex flex-col p-3 border rounded-lg bg-card">
                                        {editingId === listing.id ? (
                                            // Edit Mode
                                            <div className="space-y-3">
                                                <div className="flex items-center justify-between">
                                                    <div className="flex items-center gap-2">
                                                        <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs">
                                                            {listing.platform.substring(0, 2)}
                                                        </div>
                                                        <div>
                                                            <div className="font-medium">{listing.platform}</div>
                                                            <div className="text-xs text-muted-foreground">{formatCurrency(listing.listedPrice, listing.currency || "USD")}</div>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-1">
                                                        <Button size="icon" variant="ghost" onClick={() => saveEditing(listing.id)}>
                                                            <Check className="h-4 w-4 text-green-600" />
                                                        </Button>
                                                        <Button size="icon" variant="ghost" onClick={cancelEditing}>
                                                            <X className="h-4 w-4 text-red-600" />
                                                        </Button>
                                                    </div>
                                                </div>
                                                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                                                    <div className="space-y-1">
                                                        <label className="text-xs text-muted-foreground">Listing URL</label>
                                                        <div className="flex gap-1">
                                                            <Input
                                                                value={editValues.listingUrl}
                                                                onChange={(e) => setEditValues({ ...editValues, listingUrl: e.target.value })}
                                                                placeholder="https://..."
                                                                className="text-sm"
                                                            />
                                                            {editValues.listingUrl && (
                                                                <Button size="icon" variant="ghost" className="shrink-0" onClick={() => window.open(editValues.listingUrl, "_blank")}>
                                                                    <ExternalLink className="h-4 w-4" />
                                                                </Button>
                                                            )}
                                                        </div>
                                                    </div>
                                                    <div className="space-y-1">
                                                        <label className="text-xs text-muted-foreground">Reference / Listing ID</label>
                                                        <Input
                                                            value={editValues.listingRef}
                                                            onChange={(e) => setEditValues({ ...editValues, listingRef: e.target.value })}
                                                            placeholder="e.g. #12345"
                                                            className="text-sm"
                                                        />
                                                    </div>
                                                </div>
                                            </div>
                                        ) : (
                                            // View Mode
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center gap-3 flex-1 min-w-0">
                                                    <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs shrink-0">
                                                        {listing.platform.substring(0, 2)}
                                                    </div>
                                                    <div className="min-w-0 flex-1">
                                                        <div className="font-medium flex items-center gap-2 flex-wrap">
                                                            {listing.platform}
                                                            <Badge variant={listing.status === "ACTIVE" ? "default" : listing.status === "SOLD" ? "destructive" : "secondary"} className="text-[10px]">
                                                                {listing.status}
                                                            </Badge>
                                                        </div>
                                                        <div className="text-xs text-muted-foreground flex items-center flex-wrap gap-x-2 gap-y-1">
                                                            <span>{formatCurrency(listing.listedPrice, listing.currency || "USD")}</span>
                                                            {listing.listingRef && <span>Ref: {listing.listingRef}</span>}
                                                            <ListingPriceHistory listingId={listing.id} currency={listing.currency || "USD"} />
                                                        </div>
                                                        {listing.listingUrl && (
                                                            <div className="flex items-center gap-1 mt-1">
                                                                <Link2 className="h-3 w-3 text-muted-foreground" />
                                                                <a 
                                                                    href={listing.listingUrl} 
                                                                    target="_blank" 
                                                                    rel="noopener noreferrer" 
                                                                    className="text-xs text-primary hover:underline truncate max-w-[250px]"
                                                                    title={listing.listingUrl}
                                                                >
                                                                    {listing.listingUrl.length > 40 ? listing.listingUrl.substring(0, 40) + "..." : listing.listingUrl}
                                                                </a>
                                                                <Button size="icon" variant="ghost" className="h-5 w-5" onClick={() => copyToClipboard(listing.listingUrl!)}>
                                                                    <Link2 className="h-3 w-3" />
                                                                </Button>
                                                                <Button size="icon" variant="ghost" className="h-5 w-5" onClick={() => window.open(listing.listingUrl!, "_blank")}>
                                                                    <ExternalLink className="h-3 w-3" />
                                                                </Button>
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-1 shrink-0">
                                                    <Button variant="ghost" size="icon" onClick={() => startEditing(listing)} title="Edit listing URL">
                                                        <Pencil className="h-4 w-4" />
                                                    </Button>
                                                    <Select defaultValue={listing.status} onValueChange={(val) => handleStatusChange(listing.id, val)}>
                                                        <SelectTrigger className="h-8 w-[100px]">
                                                            <SelectValue />
                                                        </SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="ACTIVE">Active</SelectItem>
                                                            <SelectItem value="PAUSED">Paused</SelectItem>
                                                            <SelectItem value="SOLD">Sold</SelectItem>
                                                            <SelectItem value="REMOVED">Removed</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                    <Button variant="ghost" size="icon" onClick={() => handleDelete(listing.id)}>
                                                        <Trash2 className="h-4 w-4 text-destructive" />
                                                    </Button>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}
